import re, json, os

BLOCKS = 'storage/shared/agency_lab/data/progressor/raw_eval_logs/eval_blocks.jsonl'
OUT_SUM = 'storage/shared/agency_lab/data/progressor/raw_eval_logs/extraction_summary_v0_1.json'

AGENT_RE = re.compile(r'(Agent_[0-9]+)\\s*\\(Gen\\s*(\\d+)\\)', re.IGNORECASE)

def brace_extract_dict(text, start_idx):
    # Find first '{' after start_idx, then match braces
    n = len(text)
    i = text.find('{', start_idx)
    if i == -1:
        return None, -1
    depth = 0
    in_str = False
    esc = False
    quote = ''
    for j in range(i, n):
        ch = text[j]
        if in_str:
            if esc:
                esc = False
            elif ch == '\\\\':
                esc = True
            elif ch == quote:
                in_str = False
        else:
            if ch in ('"', "'"):
                in_str = True
                quote = ch
            elif ch == '{':
                depth += 1
            elif ch == '}':
                depth -= 1
                if depth == 0:
                    return text[i:j+1], j+1
    return None, -1

def to_json_obj(s):
    # Heuristic sanitize from Python-ish to JSON
    s2 = s
    # Replace True/False/None
    s2 = re.sub(r'\\bTrue\\b', 'true', s2)
    s2 = re.sub(r'\\bFalse\\b', 'false', s2)
    s2 = re.sub(r'\\bNone\\b', 'null', s2)
    # Convert single quotes to double quotes cautiously: replace only when balanced outside of quotes is hard, do simple pass:
    # First, avoid disturbing quotes inside double-quoted substrings; naive approach: if no double-quotes, replace singles.
    if s2.count('"') < 2:
        s2 = s2.replace("'", '"')
    else:
        # Fallback global replace which works in most logs
        s2 = s2.replace("'", '"')
    # Remove trailing commas before } or ]
    s2 = re.sub(r',\\s*([}\\]])', r'\\1', s2)
    try:
        return json.loads(s2)
    except Exception:
        return None

def find_agent_before(text, pos, lookback=400):
    start = max(0, pos - lookback)
    m = None
    for m in AGENT_RE.finditer(text[start:pos]):
        pass
    if m:
        return m.group(1), int(m.group(2))
    return None, None

def extract_strategies_from_block(content):
    out = {}
    pos = 0
    marker = 'action_strategy'
    while True:
        k = content.find(marker, pos)
        if k == -1:
            break
        # Extract dict after the defaultdict( ... , { ... } )
        # Find the comma after the first '(' to ensure we start dict after args
        paren = content.find('(', k)
        if paren == -1:
            pos = k + len(marker)
            continue
        # Try to locate the comma separating factory and dict
        comma = content.find(',', paren)
        scan_from = comma+1 if comma != -1 else paren+1
        dict_str, new_pos = brace_extract_dict(content, scan_from)
        if not dict_str:
            pos = k + len(marker)
            continue
        obj = to_json_obj(dict_str)
        agent_id, gen = find_agent_before(content, k)
        key = agent_id or f'Agent_unknown_{len(out)+1}'
        if obj is not None:
            out[key] = obj
        pos = new_pos
    return out

def main():
    results = []
    total_blocks = 0
    found_any = 0
    per_eval_counts = {}
    with open(BLOCKS, 'r', encoding='utf-8') as f:
        for line in f:
            if not line.strip():
                continue
            total_blocks += 1
            rec = json.loads(line)
            eid = rec.get('eval_id')
            content = rec.get('log_content') or ''
            strategies = extract_strategies_from_block(content)
            per_eval_counts[eid] = len(strategies)
            if strategies:
                found_any += 1
            # Build a compact per-eval summary
            top_actions = {}
            for aid, strat in strategies.items():
                if isinstance(strat, dict):
                    # Count action keys at top-level
                    top_actions[aid] = list(strat.keys())[:5]
            results.append({
                "eval_id": eid,
                "strategies_found": len(strategies),
                "agents": sorted(list(strategies.keys())),
                "sample_actions_per_agent": top_actions
            })
    summary = {
        "blocks": total_blocks,
        "evals_with_strategies": found_any,
        "per_eval_counts": per_eval_counts,
        "details": results
    }
    os.makedirs(os.path.dirname(OUT_SUM), exist_ok=True)
    with open(OUT_SUM, 'w', encoding='utf-8') as out:
        json.dump(summary, out, indent=2, ensure_ascii=False)
    print(json.dumps(summary, indent=2, ensure_ascii=False))

if __name__ == "__main__":
    main()

